var leaves = [];

function setup() {
	createCanvas(windowWidth, windowHeight);
	noStroke();
	var total = 1000;
	for(let i = 0; i < total; i++){
		var r = sqrt(i/total/10+0.005) * 1000 - 70;
		var a = i/total * 3002;
		var x = cos(a) * r + width/2;
		var y = sin(a) * r + height/2;
		var size = random(10, 30);
		var col = color(random(50), random(100, 200), random(50));
		leaves.push({x, y, size, angle:a-PI/4, color:col});
	}

	var context = this.drawingContext; // or p5.drawingContext
	context.shadowOffsetX = 5;
	context.shadowOffsetY = -5;
	context.shadowBlur = 10;
	context.shadowColor = '#000';
}

function draw() {
	background(0);
	var time = frameCount / 50;
	leaves.forEach((leaf, index, arr) => {
		var size = abs(sin(index + time) * leaf.size);
		fill(leaf.color);
		push();
			translate(leaf.x, leaf.y);
			rotate(leaf.angle);
			rect(0, 0, size, size, 0, size / 2, 0, size / 2);
		pop();
	});
}
